# Let's run a detailed script to verify the exact outbound messages and state.
import json

class Simulator:
    def __init__(self, config, store):
        self.config = config
        self.status = store["status"]
        self.next_sender_seq_num = store["next_sender_seq_num"]
        self.next_target_seq_num = store["next_target_seq_num"]
        self.working_orders = list(store["working_orders"])
        self.pods = {
            "pod-alpha": {"crashed": False, "crash_time": None},
            "pod-beta": {"crashed": False, "crash_time": None}
        }
        self.outbound_messages = []
        self.disconnect_time_ms = None

    def send_msg(self, msg, timestamp):
        self.outbound_messages.append(msg)
        self.next_sender_seq_num += 1

    def handle_event(self, event):
        etype = event["event_type"]
        t = event["timestamp_ms"]

        if etype == "POD_CRASH":
            pod_id = event["pod_id"]
            self.pods[pod_id]["crashed"] = True
            self.pods[pod_id]["crash_time"] = t

        elif etype == "POD_RECONNECT":
            pod_id = event["pod_id"]
            self.pods[pod_id]["crashed"] = False
            self.pods[pod_id]["crash_time"] = None

        elif etype == "RECV_MSG":
            if event["msg_seq_num"] == self.next_target_seq_num:
                self.next_target_seq_num += 1
            # Update order state if 35=8
            if event.get("msg_type") == "8":
                cl_ord_id = event.get("cl_ord_id")
                leaves_qty = event.get("leaves_qty")
                for o in self.working_orders:
                    if o["cl_ord_id"] == cl_ord_id:
                        o["leaves_qty"] = leaves_qty
                        if leaves_qty == 0:
                            o["status"] = "FILLED"

        elif etype == "CLOCK_TICK":
            # Check grace timeouts for crashed pods
            # pod-alpha crashed at 10000, grace timeout = 5000 -> expires at 15000.
            # At t=15000, alpha grace expires!
            for pod_id, pinfo in self.pods.items():
                if pinfo["crashed"] and pinfo["crash_time"] is not None:
                    if t >= pinfo["crash_time"] + self.config["pod_grace_timeout_ms"]:
                        # Timeout reached! Cancel working orders for this pod.
                        orders_to_cancel = [o for o in self.working_orders if o["pod_id"] == pod_id and o["status"] == "WORKING"]
                        for o in orders_to_cancel:
                            # Send OrderCancelRequest (35=F) upstream
                            msg = {
                                "msg_type": "F",
                                "msg_seq_num": self.next_sender_seq_num,
                                "poss_dup_flag": False,
                                "send_time_ms": t,
                                "cl_ord_id": "FG-cancel-" + o["cl_ord_id"],
                                "orig_cl_ord_id": o["cl_ord_id"]
                            }
                            self.send_msg(msg, t)
                            o["status"] = "PENDING_CANCEL"
                        # clear crash info so it doesn't trigger again
                        pinfo["crash_time"] = None

sim = Simulator(task["engine_config"], task["initial_store"])
for ev in task["inbound_event_trace"]:
    sim.handle_event(ev)

print(json.dumps({
